### 🔧 PASO 2: Reemplaza `@/components/I18nProvider.tsx`
Este archivo expone el contexto, el hook `useI18n` y el componente `I18nProvider` exactamente como lo espera tu `Layout`.

```tsx
// components/I18nProvider.tsx
"use client";

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Lang, defaultLang, getT, TranslationKeys } from '@/utils/translations';

type I18nContextType = {
  lang: Lang;
  t: TranslationKeys;
  setLang: (lang: Lang) => void;
};

const I18nContext = createContext<I18nContextType | undefined>(undefined);

export function useI18n(): I18nContextType {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error('useI18n must be used within I18nProvider');
  return ctx;
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(defaultLang);

  useEffect(() => {
    const saved = localStorage.getItem('dual_scars_lang') as Lang | null;
    if (saved && ['es', 'ca', 'en'].includes(saved)) setLangState(saved);
  }, []);

  const setLang = (newLang: Lang) => {
    setLangState(newLang);
    localStorage.setItem('dual_scars_lang', newLang);
  };

  const t = getT(lang);

  return (
    <I18nContext.Provider value={{ lang, t, setLang }}>
      {children}
    </I18nContext.Provider>
  );
}
```

