    emergency: { title: '🛑 EMERGENCY ANCHOR', step1: '1. Breathe: 4s inhale, 6s exhale.', step2: '2. Validate: What you feel is real. It\'s not "in your head".', step3: '3. Act: Call 112 or your local crisis line. Save this log.', close: 'Close & Hide' },
